/**
 * NASA Blue Marble / Visible Earth equirectangular texture (public domain),
 * 2048x1024, embedded as a base64 data URL so the globe never depends on an
 * external URL at runtime. Source:
 * https://unpkg.com/three-globe/example/img/earth-blue-marble.jpg
 * (NASA Visible Earth, public domain).
 *
 * The oceans in the source image carry bathymetry / ocean-colour mottling
 * that reads as blotches on the globe, so the ocean pixels were replaced
 * with a heavily blurred version of themselves (radius 80px, ocean-only,
 * feathered at the coasts): the seas are now a smooth deep blue and the
 * land - coastlines included - is untouched. The blur was done on a copy
 * tiled three times horizontally so it wraps around the antimeridian and
 * the texture stays seamless at lon +-180.
 */

export const EARTH_TEXTURE_DATA_URL =
  'data:image/jpeg;base64,';
